(() => {
'use strict';
if(window.__franklinExtendedEngine)return;window.__franklinExtendedEngine=true;
const DISCORD='https://discord.gg/HgcbPjcyJ';
const STOP=new Set('a an the is are was were be to of in on at for from with and or but if then than so do does did can could would should will may might i me my you your we our they their it its this that these those what why how when where who which about please tell say give get have has had yang dan atau di ke dari untuk pada dengan ini itu saya aku gue kamu anda tentang apa bagaimana gimana kenapa apakah bisa tidak nggak ga gak tolong kasih jelaskan'.split(/\s+/));
const ALIASES={unduh:'install',download:'install',pasang:'install',setup:'install',sideload:'install',ipa:'install',hp:'device',phone:'device',iphone:'device',perangkat:'device',support:'compatibility',supported:'compatibility',ram:'memory',lowmem:'memory',memrestrict:'memory',lag:'performance',stutter:'performance',fps:'performance',panas:'performance',hot:'performance',thermal:'performance',crash:'troubleshooting',error:'troubleshooting',freeze:'troubleshooting',update:'updates',version:'updates',build:'updates',terbaru:'updates',latest:'updates',gamepad:'controller',joystick:'controller',touch:'controls',car:'vehicle',cars:'vehicle',kendaraan:'vehicle',mobil:'vehicle',gun:'weapon',guns:'weapon',senjata:'weapon',mission:'missions',missions:'missions',misi:'missions',heist:'heists',map:'world',peta:'world',lokasi:'world',cerita:'story',plot:'story',campaign:'story',kode:'cheats',uang:'money',cash:'money',online:'multiplayer',savegame:'save',saves:'save',backup:'save',shadow:'graphics',shadows:'graphics',resolution:'graphics',metalfx:'graphics',msaa:'graphics',sound:'audio',suara:'audio',storage:'storage',space:'storage'};
const state={entries:null,promise:null,lastQuestion:'',lastTopic:'',entities:{},history:[]};
const norm=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/gta\s*5/g,'gta v').replace(/[^a-z0-9+.-]+/g,' ').replace(/\s+/g,' ').trim();
const raw=v=>norm(v).split(' ').filter(Boolean);
const tokens=v=>[...new Set(raw(v).flatMap(t=>t.length<2||STOP.has(t)?[]:[t,...(ALIASES[t]&&ALIASES[t]!==t?[ALIASES[t]]:[])]))];
const dist=(a,b)=>{if(a===b)return 0;if(Math.abs(a.length-b.length)>3)return 4;let p=Array.from({length:b.length+1},(_,i)=>i),c=[];for(let i=1;i<=a.length;i++){c[0]=i;let m=i;for(let j=1;j<=b.length;j++){c[j]=Math.min(c[j-1]+1,p[j]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));m=Math.min(m,c[j]);}if(m>3)return 4;[p,c]=[c,p];}return p[b.length];};
const fuzzy=(a,b)=>a===b?1:(a.length<4||b.length<4?0:(d=>d>3?0:1-d/Math.max(a.length,b.length))(dist(a,b)));
const overlap=(a,b)=>{if(!a.length||!b.length)return 0;const s=new Set(b);return a.filter(x=>s.has(x)).length/a.length};
function load(){if(state.promise)return state.promise;state.promise=fetch('franklin-knowledge-extra.json',{cache:'no-cache'}).then(r=>r.ok?r.json():{entries:[]}).then(d=>state.entries=(d.entries||[]).map(e=>({...e,_patterns:(e.patterns||[]).map(norm),_keywords:[...new Set((e.keywords||[]).flatMap(tokens))]}))).catch(()=>state.entries=[]);return state.promise;}
function entities(q){const n=norm(q),o={};const d=n.match(/\biphone\s*(\d{1,2})(?:\s*(pro|max|mini|plus))?\b/);if(d)o.device=`iPhone ${d[1]}${d[2]?' '+d[2][0].toUpperCase()+d[2].slice(1):''}`;const r=n.match(/\b(3|4|6|8|12|16)\s*gb\b/);if(r)o.memory=`${r[1]} GB`;return o;}
function context(q){const n=norm(q),follow=raw(n).length<=8&&(/^(and|what about|how about|why|how|where|when|can it|does it|is it|that|it|then|so)\b/.test(n)||/\b(it|that|this one|same thing|those settings)\b/.test(n));if(!follow||!state.lastQuestion)return q;return `${state.lastQuestion} ${q} ${state.lastTopic} ${Object.values(state.entities).join(' ')}`;}
function score(e,q,qt){let s=0,n=norm(q);for(const p of e._patterns){if(n===p)s+=20;else if(n.includes(p)||p.includes(n))s+=Math.min(12,4+p.length/10);s+=overlap(qt,tokens(p))*5.4;}for(const t of qt){if(e._keywords.includes(t))s+=t.length>=7?3.5:2.5;else{let f=0;for(const k of e._keywords)f=Math.max(f,fuzzy(t,k));if(f>=.84)s+=1.6*f;}}if(state.lastTopic&&e.topic===state.lastTopic&&raw(q).length<=7)s+=3;return s;}
async function extended(q){const es=await load(),qt=tokens(q),rank=es.map(e=>({e,s:score(e,q,qt)})).sort((a,b)=>b.s-a.s),b=rank[0],floor=qt.length<=2?4.4:Math.min(9,3.8+qt.length*.68);return b&&b.s>=floor?b:null;}
function remember(q,r){state.lastQuestion=q;if(r.topic)state.lastTopic=r.topic;state.entities={...state.entities,...entities(q)};state.history.push({q,topic:r.topic||''});if(state.history.length>6)state.history.shift();}
const related=t=>({installation:['How do I update safely?','What if signing expires?'],compatibility:['Best settings for 4 GB?','What causes thermal throttling?'],performance:['Should I use 30 or 40 FPS?','What does MetalFX do?'],graphics:['What resolution should I use?','Should I use MSAA?'],troubleshooting:['What if I get a black screen?','What if loading never finishes?'],characters:['Tell me about the three protagonists','Who is Lester?'],story:['How many endings are there?','What is the Big Score?'],heists:['What is the Big Score?','What is the Paleto Score?'],world:['Where is Mount Chiliad?','What is Sandy Shores?'],vehicles:['How do garages work?','Can I customize cars?'],multiplayer:['GTA Online vs Story Mode','Does GTA Online work on this iOS project?']}[t]||[]);
async function answer(q){const en=context(q),hit=await extended(en);if(hit){const r={text:hit.e.answer,topic:hit.e.topic||'',source:hit.e.source||null,discord:hit.e.discord===true,suggestions:related(hit.e.topic)};remember(q,r);return r;}const e={...state.entities,...entities(q)},wants=/\b(settings?|preset|graphics|performance|fps|resolution)\b/.test(norm(q));if(wants&&(e.device||e.memory)){const lead=e.device?`Since we're talking about your ${e.device}${e.memory?' with '+e.memory+' of memory':''},`:`For that ${e.memory||'device'},`;const r={text:`${lead} start conservative: lower render resolution, keep MSAA off, use modest shadows, enable low-memory mode if your launcher build provides it, and prefer a stable FPS cap over an unstable higher target. Raise one setting at a time while watching heat and memory pressure.`,topic:'performance',source:{href:'compatibility.html',label:'Compatibility'},suggestions:related('performance')};remember(q,r);return r;}if(window.FranklinEngine?.answer){const r=await window.FranklinEngine.answer(en);remember(q,r||{});return r;}return{text:"Aight, I don't have a solid answer for that one yet, homie. Join the Discord and ask the staff or community directly.",discord:true};}
const svg=n=>`<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${n}"></use></svg>`;
function bot(text,o={}){const m=document.querySelector('.ask-franklin-messages');if(!m)return;const row=document.createElement('div');row.className='ask-franklin-message bot franklin-extended-message';row.innerHTML='<span class="mini-avatar">F</span>';const b=document.createElement('div');b.className='bubble';b.textContent=text;row.append(b);if(o.discord){const a=document.createElement('a');a.className='ask-franklin-discord';a.href=DISCORD;a.target='_blank';a.rel='noopener noreferrer';a.innerHTML=`Ask the crew on Discord ${svg('arrow-up-right')}`;b.append(document.createElement('br'),a);}if(o.source?.href){const a=document.createElement('a');a.className='ask-franklin-discord';a.href=o.source.href;a.innerHTML=`Open ${o.source.label||'source'} ${svg('arrow-right')}`;b.append(document.createElement('br'),a);}m.append(row);if(o.suggestions?.length){const w=document.createElement('div');w.className='ask-franklin-actions ask-franklin-related';o.suggestions.slice(0,2).forEach(x=>{const c=document.createElement('button');c.type='button';c.className='ask-franklin-chip';c.textContent=x;w.append(c)});m.append(w);}requestAnimationFrame(()=>m.scrollTop=m.scrollHeight);}
function user(text){const m=document.querySelector('.ask-franklin-messages');if(!m)return;const r=document.createElement('div');r.className='ask-franklin-message user franklin-extended-message';const b=document.createElement('div');b.className='bubble';b.textContent=text;r.append(b);m.append(r);requestAnimationFrame(()=>m.scrollTop=m.scrollHeight);}
function thinking(){const m=document.querySelector('.ask-franklin-messages');if(!m)return null;const r=document.createElement('div');r.className='ask-franklin-message bot is-thinking franklin-extended-message';r.innerHTML='<span class="mini-avatar">F</span><div class="bubble" aria-label="Franklin is thinking"><i class="ask-franklin-dot"></i><i class="ask-franklin-dot"></i><i class="ask-franklin-dot"></i></div>';m.append(r);return r;}
let busy=false;async function handle(rawq){const q=String(rawq||'').trim();if(!q||busy)return;const i=document.querySelector('.ask-franklin-input'),s=document.querySelector('.ask-franklin-send');if(!i||!s)return;busy=true;s.disabled=true;user(q);i.value='';i.style.height='auto';const w=thinking();try{const r=await answer(q);await new Promise(x=>setTimeout(x,matchMedia('(prefers-reduced-motion: reduce)').matches?20:160));w?.remove();bot(r.text,r);window.gtavHaptics?.trigger?.('soft');}catch{w?.remove();bot("Man, something went sideways on my end. Try again, or ask the crew on Discord.",{discord:true});window.gtavHaptics?.trigger?.('warning');}finally{busy=false;s.disabled=!i.value.trim();i.focus({preventScroll:true});}}
document.addEventListener('submit',e=>{const f=e.target instanceof Element?e.target.closest('.ask-franklin-form'):null;if(!f)return;e.preventDefault();e.stopImmediatePropagation();handle(f.querySelector('.ask-franklin-input')?.value||'');},true);
document.addEventListener('click',e=>{if(!(e.target instanceof Element))return;const c=e.target.closest('.ask-franklin-chip');if(!c)return;e.preventDefault();e.stopImmediatePropagation();handle(c.textContent||'');},true);
window.FranklinExtended={answer,load,getContext:()=>({...state,entries:undefined,promise:undefined})};
load();
})();